const BM = {
  key:'mb_favs',
  get(){ try{ return JSON.parse(localStorage.getItem(this.key)||'[]'); }catch(e){ return []; } },
  has(s){ return this.get().includes(s); },
  toggle(s){ let a=this.get(); a=a.includes(s)?a.filter(x=>x!==s):a.concat(s);
    try{ localStorage.setItem(this.key,JSON.stringify(a)); }catch(e){} return a.includes(s); }
};

