function termCard(t){
  const fav=BM.has(t.slug);
  return `<a class="card termcard" href="#/terim/${t.slug}">
    <span class="star${fav?' on':''}" role="button" tabindex="0" aria-label="Kaydet" onclick="favTog(event,'${t.slug}')">${fav?'★':'☆'}</span>
    <div class="tagrow" style="margin:0 0 12px"><span class="tag o">${esc(t.cat)}</span><span class="tag">${esc(t.level)}</span>${t.src?'<span class="tag" style="color:var(--ok);border-color:#1E3A24">✓ kaynaklı</span>':''}</div>
    <h3>${esc(t.name)}</h3><div class="en">${esc(t.en)}</div>
    <div class="st">${esc(t.short)}</div></a>`;
}
function favTog(e,slug){ e.preventDefault(); e.stopPropagation(); BM.toggle(slug); render(); }

