/* dosya görüntüleyici */
let VF=0, VW=false, VFull=false;
function viewer(){
  const f=FILES[VF];
  return `<div class="viewer" id="viewer">
    <div class="vtabs">${FILES.map((x,i)=>`<button class="vtab${i===VF?' on':''}" onclick="setFile(${i})">${esc(x.name)}</button>`).join('')}</div>
    <div class="vbar">
      <span class="fname">${esc(f.path)} · ${f.text.split('\n').length} satır · ${(f.text.length/1024).toFixed(1)} KB</span>
      <button class="btn sm" onclick="VW=!VW;render()">${VW?'Sarma: açık':'Sarma: kapalı'}</button>
      <button class="btn sm" onclick="VFull=!VFull;render()">${VFull?'Küçült':'Tam boy'}</button>
      <button class="btn sm" onclick="copy(FILES[VF].text,FILES[VF].name+' kopyalandı')">Kopyala</button>
      <button class="btn sm" onclick="download(FILES[VF].name,FILES[VF].text)">İndir</button>
    </div>
    <div class="vcode${VW?' wrap':''}${VFull?' full':''}">${codeTable(f.text)}</div>
  </div>`;
}
function setFile(i){ VF=i; render(); setTimeout(()=>{const v=document.getElementById('viewer'); if(v) v.scrollIntoView({block:'start'});},0); }
function copyAll(){
  copy(FILES.map(f=>'==== '+f.path+' ====\n\n'+f.text).join('\n\n\n'),'4 dosyanın tamamı kopyalandı');
}

