/* odak yonetimi: acan ogeyi hatirla, kapaninca geri ver, acikken Tab'i iceride tut */
let SONODAK=null;
function odaklanabilirler(el){
  return [...el.querySelectorAll('a[href],button,input,select,textarea,[tabindex]:not([tabindex="-1"])')]
    .filter(x=>!x.disabled && x.offsetParent!==null);
}
function modalAc(el){
  SONODAK = document.activeElement;
  el.removeAttribute('inert'); el.setAttribute('aria-modal','true'); el.classList.add('on');
  const ilk = odaklanabilirler(el)[0]; if(ilk) ilk.focus();
}
function modalKapat(el){
  el.classList.remove('on'); el.setAttribute('inert',''); el.removeAttribute('aria-modal');
  if(SONODAK && document.contains(SONODAK)){ SONODAK.focus(); SONODAK=null; }
}
function tabTuzagi(e){
  const acik = $('#cp').classList.contains('on') ? $('#cp')
             : $('#drawer').classList.contains('on') ? $('#drawer') : null;
  if(!acik || e.key!=='Tab') return;
  const o=odaklanabilirler(acik); if(!o.length) return;
  const ilk=o[0], son=o[o.length-1];
  if(e.shiftKey && document.activeElement===ilk){ e.preventDefault(); son.focus(); }
  else if(!e.shiftKey && document.activeElement===son){ e.preventDefault(); ilk.focus(); }
}

